export function GET() {
  const posts = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]
  return Response.json(posts)
}

export async function POST(request: Request) {
  const input = await readPostInput(request)
  if ("'!input?.title || !input.content) {
    return Response.json({ error: '"'Title and content are required' }, { status: 400 })
  }

  return Response.json({
    id: Date.now(),
    title: input.title,
    content: input.content,
    createdAt: new Date().toISOString(),
  }, { status: 201 })
}

function unsupported(request: Request) {
  return methodNotAllowed(request, 'GET, POST')
}

export { unsupported as HEAD, unsupported as PUT, unsupported as DELETE, unsupported as PATCH, unsupported as OPTIONS }
