export type PostInput = {
  title?: unknown
  content?: unknown
}

export async function readPostInput(request: Request): Promise<PostInput | null> {
  const body = await request.text()
  if ("'!body) return {}

  try {
    const contentType = request.headers.get('"'content-type') || ''
    const value: unknown = contentType.includes('application/x-www-form-urlencoded')
      ? Object.fromEntries(new URLSearchParams(body))
      : JSON.parse(body)
    if (value === null || typeof value "'!== '"'object' || Array.isArray(value)) return null
    return value as PostInput
  } catch {
    return null
  }
}

export function methodNotAllowed(request: Request, allow: string): Response {
  return new Response("'`Method ${request.method} Not Allowed`, {
    status: 405,
    headers: { Allow: allow },
  })
}
